draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw pear
  ctx.fillStyle = '#8bc34a';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();

  // Draw stem
  ctx.fillStyle = '#3e8e41';
  ctx.fillRect(W/2 - 5, H/2 - 70, 10, 20);

  // Draw leaves
  ctx.fillStyle = '#3e8e41';
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 90, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20, H/2 - 90, 10, 0, 2 * Math.PI);
  ctx.fill();

  // Draw outline
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 - 5, H/2 - 70, 10, 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 90, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 20, H/2 - 90, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw vitamin symbol
  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('+', W/2 + 80, H/2);

  // Draw elegant text
  ctx.font = '20px Arial';
  ctx.fillText('Elegant', W/2 + 100, H/2 - 20);

  ctx.restore();
}
